contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to) public payable {
        require(to != address(0));
        require(!c.frozenAccount(to));
        uint256 tsBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 selfBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool ok = c.transfer(to, 0); if (__ESBMC_reverted()) return;
        assert(ok && c.totalSupply() == tsBefore && c.balanceOf(to) == toBefore && c.balanceOf(address(this)) == selfBefore);
    }
    receive() external payable {}
}

