    function _run(address to) internal {
        vm.assume(to != address(0));
        vm.assume(!c.frozenAccount(to));
        uint256 tsBefore;
        try c.totalSupply() returns (uint256 __r) { tsBefore = __r; } catch { return; }
        uint256 toBefore;
        try c.balanceOf(to) returns (uint256 __r) { toBefore = __r; } catch { return; }
        uint256 selfBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { selfBefore = __r; } catch { return; }
